begin;
do $$
declare u uuid:=gen_random_uuid();v uuid:=gen_random_uuid();sid uuid;other_source uuid;other_item uuid:=gen_random_uuid();jid uuid:=gen_random_uuid();a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();c uuid:=gen_random_uuid();g1 uuid;g2 uuid;job jsonb;result jsonb;eid uuid;article uuid:=gen_random_uuid();revision uuid:=gen_random_uuid();real_article uuid:=gen_random_uuid();real_revision uuid:=gen_random_uuid();
begin
 insert into auth.users(id,email) values(u,'z09-'||u||'@example.invalid'),(v,'z09-'||v||'@example.invalid');
 insert into private.profiles(id) values(u),(v);insert into private.user_roles(user_id,role) values(u,'editor');
 perform set_config('request.jwt.claim.sub',u::text,true);
 result:=api.editor_save_source(null,null,'Fixture','https://example.org/feed','example.org','rss','Prueba local',true);sid:=(result->>'id')::uuid;update private.sources set is_simulation=true where id=sid;
 insert into private.source_items(id,source_id,canonical_url,title,external_date) values(a,sid,'https://example.org/a','SIMULACIÓN Ciudad inaugura un parque',now()),(b,sid,'https://example.org/b','SIMULACIÓN Ciudad inaugura parque público',now()),(c,sid,'https://example.org/c','SIMULACIÓN Ciudad crea parque público',now());
 result:=api.editor_save_source(null,null,'Otra fuente','https://example.net/feed','example.net','rss','Prueba local',true);other_source:=(result->>'id')::uuid;
 insert into private.source_items(id,source_id,canonical_url,title,external_date) values(other_item,other_source,'https://example.net/test','Noticia de prueba',now());
 insert into private.jobs(id,job_type,payload,dedupe_key,created_by) values(jid,'event.cluster','{}','test-cluster-'||jid,u);
 perform set_config('role','riuya_job_executor',true);
 job:=private.claim_job('test-cluster',60);if job->>'id'<>jid::text then raise exception 'CLAIM_FAILED';end if;
 if private.cluster_job_info(jid,gen_random_uuid()) is not null then raise exception 'INVALID_LEASE_ACCEPTED';end if;
 begin perform private.complete_cluster_job(jid,(job->>'leaseToken')::uuid,jsonb_build_array(jsonb_build_object('a',a,'b',other_item)));raise exception 'SIMULATION_GROUP_MIXED';exception when invalid_parameter_value then null;end;
 if not private.complete_cluster_job(jid,(job->>'leaseToken')::uuid,jsonb_build_array(jsonb_build_object('a',a,'b',b),jsonb_build_object('a',b,'b',c))) then raise exception 'CLUSTER_FAILED';end if;
 if private.complete_cluster_job(jid,(job->>'leaseToken')::uuid,'[]') then raise exception 'REPLAYED_LEASE';end if;
 perform set_config('role','none',true);
 if exists(select 1 from private.source_items where id in(a,b,c) and event_id is not null) then raise exception 'AUTO_MERGE';end if;
 select id into g1 from private.source_group_proposals where item_a=least(a,b) and item_b=greatest(a,b);
 select id into g2 from private.source_group_proposals where item_a=least(b,c) and item_b=greatest(b,c);
 perform set_config('request.jwt.claim.sub',v::text,true);
 begin perform api.editor_decide_group(g1,1,'confirm');raise exception 'NONEDITOR_ACCEPTED';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',u::text,true);
 begin perform api.editor_decide_group(g1,1,null);raise exception 'NULL_DECISION_ACCEPTED';exception when invalid_parameter_value then null;end;
 result:=api.editor_decide_group(g1,1,'confirm');eid:=(result->>'eventId')::uuid;
 if eid is null or (select count(*) from private.source_items where id in(a,b) and event_id=eid)<>2 then raise exception 'CONFIRM_FAILED';end if;
 begin perform api.editor_decide_group(g1,1,'confirm');raise exception 'REPLAYED_DECISION';exception when sqlstate 'PT409' then null;end;
 result:=api.editor_decide_group(g2,1,'reject');if result->>'status'<>'rejected' or (select event_id from private.source_items where id=c) is not null then raise exception 'REJECT_FAILED';end if;
 insert into private.articles(id,category_id) select article,id from private.categories limit 1;
 insert into private.article_revisions(id,article_id,revision_number,title,micro_summary,full_paragraphs) values(revision,article,1,'SIMULACIÓN publicación','Prueba','[]');
 update private.articles set status='published',current_revision_id=revision,published_at=now() where id=article;
 begin perform api.editor_set_event_primary(eid,1,article,1,false);raise exception 'PRIMARY_WITHOUT_CONFIRM';exception when invalid_parameter_value then null;end;
 insert into private.articles(id,category_id) select real_article,id from private.categories limit 1;
 insert into private.article_revisions(id,article_id,revision_number,title,micro_summary,full_paragraphs) values(real_revision,real_article,1,'Noticia de prueba sin etiqueta ficticia','Prueba','[]');
 update private.articles set status='published',current_revision_id=real_revision,published_at=now() where id=real_article;
 begin perform api.editor_set_event_primary(eid,1,real_article,1,true);raise exception 'SIMULATION_MIXED';exception when invalid_parameter_value then null;end;
 perform set_config('request.jwt.claim.sub',v::text,true);
 begin perform api.editor_set_event_primary(eid,1,article,1,true);raise exception 'PRIMARY_NONEDITOR';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',u::text,true);
 result:=api.editor_set_event_primary(eid,1,article,1,true);
 if (result->>'articleId')::uuid<>article or (select primary_article_id from private.events where id=eid)<>article or (select event_id from private.articles where id=article)<>eid then raise exception 'PRIMARY_FAILED';end if;
 begin perform api.editor_set_event_primary(eid,1,article,1,true);raise exception 'PRIMARY_STALE_ACCEPTED';exception when sqlstate 'PT409' then null;end;
end $$;
rollback;
